class CrestApiFsUpdateTagTest : public ::testing::Test {
 protected:
  std::string m_root;

  void SetUp() override {
    m_root =
        "/tmp/crest_fs_update_tag_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

  void TearDown() override { std::filesystem::remove_all(m_root); }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Store one JSON payload at since through the given client
  ////////////////////////////////////////////////////////////////////////////////
  static void storeOne(CrestApiFs &api, const std::string &tagName,
                       uint64_t since) {
    StoreSetDto storeSet;
    storeSet.push_back(StoreDto(since, "", "payload " + std::to_string(since)));
    api.storeData(tagName, storeSet, "JSON", "test", "none", "1", 0);
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Create a tag holding IOVs at since 100 and 200, in a client that
  ///         is then dropped
  ////////////////////////////////////////////////////////////////////////////////
  void createTagWithTwoIovs(const std::string &tagName) {
    CrestApiFs api(true, m_root);
    TagDto tag(tagName, "time", "updateTag test tag");
    api.createTag(tag);
    storeOne(api, tagName, 100);
    storeOne(api, tagName, 200);
    ASSERT_EQ(api.getSize(tagName), 2);
  }
}

void SetUp() override {
    m_root =
        "/tmp/crest_fs_update_tag_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

static void storeOne(CrestApiFs &api, const std::string &tagName,
                       uint64_t since) {
    StoreSetDto storeSet;
    storeSet.push_back(StoreDto(since, "", "payload " + std::to_string(since)));
    api.storeData(tagName, storeSet, "JSON", "test", "none", "1", 0);
  }

void createTagWithTwoIovs(const std::string &tagName) {
    CrestApiFs api(true, m_root);
    TagDto tag(tagName, "time", "updateTag test tag");
    api.createTag(tag);
    storeOne(api, tagName, 100);
    storeOne(api, tagName, 200);
    ASSERT_EQ(api.getSize(tagName), 2);
  }

TEST_F(CrestApiFsUpdateTagTest, StoreAfterUpdateTagKeepsExistingIovs) {
  const std::string tagName = uniqueTagName("fs_update_tag");
  createTagWithTwoIovs(tagName);

  // A fresh client, as a later process would be: nothing in memory yet.
  CrestApiFs api(true, m_root);
  TagDto tag(tagName, "time", "updated description");
  api.updateTag(tag);
  storeOne(api, tagName, 300);

  EXPECT_EQ(api.getSize(tagName), 3);
  EXPECT_EQ(api.findTag(tagName).getDescription(), "updated description");
}

TEST_F(CrestApiFsUpdateTagTest, CreateTagAfterUpdateTagKeepsExistingIovs) {
  const std::string tagName = uniqueTagName("fs_update_tag");
  createTagWithTwoIovs(tagName);

  CrestApiFs api(true, m_root);
  TagDto tag(tagName, "time", "updated description");
  api.updateTag(tag);
  // Switching to another tag flushes the client's pending IOV lists.
  TagDto other(uniqueTagName("fs_update_tag_other"), "time", "other tag");
  api.createTag(other);

  EXPECT_EQ(api.getSize(tagName), 2);
}
